/* \u2500\u2500 \u06A9\u0627\u0634\u06CC\u200C\u0647\u0627 \u0648 \u0648\u06CC\u062C\u062A\u200C\u0647\u0627\u06CC \u0631\u0646\u06AF\u06CC (\u0645\u062A\u0631\u0648) \u2190 \u0634\u06CC\u0634\u0647\u0654 \u0631\u0646\u06AF\u06CC \u0628\u0627 \u062A\u0631\u0627\u0634\u0647\u0654 \u0622\u06CC\u06A9\u0646 \u0628\u0631\u0627\u0642 \u2500\u2500
   \u0631\u0646\u06AF \u0647\u0631 \u06A9\u0627\u0634\u06CC \u0627\u0632 \u0645\u062A\u063A\u06CC\u0631 --tc \u0645\u06CC\u200C\u0622\u06CC\u062F (\u062F\u0631 \u06A9\u062F \u06A9\u0627\u0634\u06CC\u200C\u0647\u0627 \u06AF\u0630\u0627\u0634\u062A\u0647 \u0634\u062F\u0647)\u061B \u0634\u06CC\u0634\u0647 \u0628\u0627 \u0647\u0645\u0627\u0646 \u0631\u0646\u06AF \u062A\u06CC\u0646\u062A \u0645\u06CC\u200C\u0634\u0648\u062F\u060C \u0646\u0647 \u0631\u0646\u06AF \u062A\u062E\u062A. */
